import React from 'react';

const TABS = [
  { id: 'home',      label: 'Home',    icon: <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M3 12L12 4l9 8"/><path d="M5 10v9h4v-4h4v4h5v-9"/></svg> },
  { id: 'checkin',   label: 'Day',     icon: <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="9"/><path d="M8 12l3 3 5-5"/></svg> },
  { id: 'history',   label: 'Log',     icon: <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg> },
  { id: 'breathing', label: 'Breathe', icon: <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M12 4c0 0-4 3-4 7s4 5 4 9"/><path d="M12 4c0 0 4 3 4 7s-4 5-4 9"/></svg> },
];

export default function Nav({ page, setPage }) {
  return (
    <div style={{
      position: 'fixed',
      bottom: 28,
      left: '50%',
      transform: 'translateX(-50%)',
      zIndex: 300,
      display: 'flex',
      alignItems: 'center',
      gap: 3,
      // liquid glass base
      background: 'rgba(255,255,255,0.07)',
      border: '1px solid rgba(255,255,255,0.1)',
      borderRadius: 999,
      padding: 5,
      backdropFilter: 'blur(24px)',
      WebkitBackdropFilter: 'blur(24px)',
      boxShadow: '0 1px 0 rgba(255,255,255,0.12) inset, 0 8px 32px rgba(0,0,0,0.35)',
    }}>
      {/* top sheen */}
      <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '50%', borderRadius: '999px 999px 0 0', background: 'linear-gradient(180deg, rgba(255,255,255,0.1) 0%, transparent 100%)', pointerEvents: 'none' }} />

      {TABS.map(tab => {
        const active = page === tab.id;
        return (
          <button
            key={tab.id}
            onClick={() => setPage(tab.id)}
            aria-label={tab.label}
            style={{
              height: 38,
              minWidth: 38,
              borderRadius: 999,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: active ? '0 14px' : '0 11px',
              background: active
                ? 'linear-gradient(160deg, rgba(200,240,240,0.18) 0%, rgba(126,200,200,0.1) 100%)'
                : 'transparent',
              boxShadow: active
                ? '0 1px 0 rgba(255,255,255,0.15) inset, 0 0 0 1px rgba(126,200,200,0.22)'
                : 'none',
              color: active ? '#7EC8C8' : 'rgba(255,255,255,0.25)',
              border: 'none',
              cursor: 'pointer',
              transition: 'all 0.35s cubic-bezier(0.34,1.2,0.64,1)',
              overflow: 'hidden',
              whiteSpace: 'nowrap',
              WebkitTapHighlightColor: 'transparent',
              position: 'relative',
            }}
          >
            {tab.icon}
            <span style={{
              fontSize: 11,
              fontWeight: 600,
              letterSpacing: '-0.01em',
              color: '#7EC8C8',
              maxWidth: active ? 60 : 0,
              overflow: 'hidden',
              marginLeft: active ? 7 : 0,
              transition: 'max-width 0.35s cubic-bezier(0.34,1.2,0.64,1), margin 0.35s',
              whiteSpace: 'nowrap',
            }}>
              {tab.label}
            </span>
          </button>
        );
      })}
    </div>
  );
}
